document.addEventListener("DOMContentLoaded", () => {
  function e(e) {
    let t = e.closest(".faq__column"),
      l = t.querySelector(".faq__wrapper"),
      r = l.querySelector("p"),
      i = t.querySelector(".faq__indicator"),
      a = document.querySelectorAll(".faq__column");
    a.forEach((e) => {
      e !== t &&
        e.classList.contains("active") &&
        (e.classList.remove("active"),
        e.querySelector(".faq__indicator").classList.remove("active"),
        (e.querySelector(".faq__wrapper p").style.maxHeight = null));
    });
    let c = t.classList.contains("active");
    i.classList.toggle("active", !c),
      c
        ? ((r.style.maxHeight = null), t.classList.remove("active"))
        : ((r.style.maxHeight = r.scrollHeight + "px"),
          t.classList.add("active"));
  }
  document.querySelectorAll(".menu-list-link").forEach((e) => {
    e.addEventListener("click", function (e) {
      e.preventDefault();
      let t = this.getAttribute("href").substring(1),
        l = document.getElementById(t);
      if (l) {
        let r = document.querySelector("header").offsetHeight,
          i = l.getBoundingClientRect().top + window.scrollY - r;
        window.scrollTo({ top: i, behavior: "smooth" });
      }
    });
  }),
    document.querySelectorAll(".faq__indicator").forEach((t) => {
      t.addEventListener("click", (l) => {
        l.stopPropagation(), e(t);
      });
    }),
    document.querySelectorAll(".faq__wrapper").forEach((t) => {
      t.addEventListener("click", () => {
        e(t);
      });
    });
  let t = document.querySelectorAll(".primary__tab-button"),
    l = document.querySelectorAll(".primary__swiper");
  t.forEach((e) => {
    e.addEventListener("click", () => {
      let r = e.dataset.tab;
      t.forEach((t) => t.classList.toggle("active", t === e)),
        l.forEach((e) => {
          e.id === r ? e.classList.remove("hide") : e.classList.add("hide");
        });
    });
  });
  let r = null,
    i = [];
  function a() {
    let e = window.innerWidth;
    e <= 1024 && !r
      ? (r = new Swiper(".work__swiper", {
          slidesPerView: "auto",
          spaceBetween: 20,
          pagination: { el: ".work__pagination", clickable: !0 },
        }))
      : e > 1024 && r && (r.destroy(!0, !0), (r = null)),
      e <= 768 && 0 === i.length
        ? document.querySelectorAll(".primary__swiper").forEach((e) => {
            let t = new Swiper(e, {
              slidesPerView: "auto",
              pagination: {
                el: e.querySelector(".primary__swiper-controls"),
                clickable: !0,
              },
            });
            i.push(t);
          })
        : e > 768 &&
          i.length > 0 &&
          (i.forEach((e) => e.destroy(!0, !0)), (i = []));
  }
  a(),
    window.addEventListener("resize", () => {
      a();
    });
});

